using Npgsql;
using PaymentService.Application;
using PaymentService.Domain;
namespace PaymentService.Infrastructure; public sealed class PostgresPaymentRepository(string cs) : IPaymentRepository { private NpgsqlConnection Db() => new(cs); public async Task<Payment> CreateAsync(Payment x, CancellationToken ct) { await using var db = Db(); await db.OpenAsync(ct); await using var c = new NpgsqlCommand("INSERT INTO payment(payment_uid,status,price) VALUES(@u,@s,@p)", db); c.Parameters.AddWithValue("u", x.PaymentUid); c.Parameters.AddWithValue("s", x.Status.ToString()); c.Parameters.AddWithValue("p", x.Price); await c.ExecuteNonQueryAsync(ct); return x; } public async Task<Payment?> GetAsync(Guid u, CancellationToken ct) { await using var db = Db(); await db.OpenAsync(ct); await using var c = new NpgsqlCommand("SELECT payment_uid,status,price FROM payment WHERE payment_uid=@u", db); c.Parameters.AddWithValue("u", u); await using var x = await c.ExecuteReaderAsync(ct); return await x.ReadAsync(ct) ? new(x.GetGuid(0), Enum.Parse<PaymentStatus>(x.GetString(1)), x.GetInt32(2)) : null; } public async Task<bool> CancelAsync(Guid u, CancellationToken ct) { await using var db = Db(); await db.OpenAsync(ct); await using var c = new NpgsqlCommand("UPDATE payment SET status='CANCELED' WHERE payment_uid=@u", db); c.Parameters.AddWithValue("u", u); return await c.ExecuteNonQueryAsync(ct) > 0; } }
